-- Classic 1.60: vanilla (VMaNGOS 1.12) school and mechanic immunities of the creatures that have any (a row of their own, ID 5000000 + entry).
-- Generated by tools/classic_spell_values/gen_creature_immunities.py. Safe to run again.
DROP TEMPORARY TABLE IF EXISTS `tmp_classic_immunity`;
CREATE TEMPORARY TABLE `tmp_classic_immunity` (`entry` int unsigned NOT NULL PRIMARY KEY, `school` tinyint unsigned NOT NULL, `mech` bigint unsigned NOT NULL);
SELECT 5000000 + m.`entry`, m.`school`, COALESCE(i.`DispelTypeMask`, 0), m.`mech`, COALESCE(i.`Effects`, ''), COALESCE(i.`Auras`, ''), COALESCE(i.`ImmuneAoE`, 0), COALESCE(i.`ImmuneChain`, 0), CONCAT('vanilla ', t.`name`)
FROM `tmp_classic_immunity` m JOIN `creature_template` t ON t.`entry` = m.`entry`
LEFT JOIN `creature_immunities` i ON i.`ID` = IF(t.`CreatureImmunitiesId` BETWEEN 5000000 AND 5999999, 5000000 + t.`entry`, t.`CreatureImmunitiesId`);
UPDATE `creature_template` t JOIN `tmp_classic_immunity` m ON m.`entry` = t.`entry` SET t.`CreatureImmunitiesId` = 5000000 + t.`entry`;
DROP TEMPORARY TABLE `tmp_classic_immunity`;
